define(["jquery","core/notification","core/str"],function($,Notification,Str){const confirmDelete=proceed=>{Promise.all([Str.get_string("deletecaptionconfirm","videoprogress"),Str.get_string("confirmdelete","videoprogress"),Str.get_string("cancel","videoprogress")]).then(strings=>Notification.confirm("",strings[0],strings[1],strings[2],proceed))};const init=()=>{$(document).on("click",'a[data-action="delete-caption"]',function(event){event.preventDefault();const href=this.getAttribute("href");confirmDelete(()=>{window.location.href=href})});$(document).on("submit",'form[data-action="delete-caption"]',function(event){if(this.dataset.confirmed==="1"){return}event.preventDefault();const form=this;confirmDelete(()=>{form.dataset.confirmed="1";form.submit()})})};return{init:init}});
